{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_deployment_name dep, metric, count(*) n, min(time) t0, max(time) t1, round(avg(value),3) av FROM abnormal_metrics WHERE attr_k8s_deployment_name = 'profile' GROUP BY ALL ORDER BY 2",
          "claim": "In the abnormal window the profile deployment reports only deployment.available/desired from 05:16:35 onward and no pod metrics."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name pod, count(*) n, min(time) t0, max(time) t1 FROM normal_metrics WHERE attr_k8s_deployment_name = 'profile' GROUP BY ALL",
          "claim": "In the normal window the sole profile pod profile-c767d64c5-zzpk2 emits metrics from 05:11:25 to 05:16:10, then disappears."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, span_name, count(*) n FROM abnormal_traces WHERE service_name='profile' GROUP BY ALL UNION ALL SELECT 'norm', span_name, count(*) FROM normal_traces WHERE service_name='profile' GROUP BY ALL",
          "claim": "The profile service emits spans in the normal period (~1190 GetProfiles) and none in the abnormal period."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT min(time) first_t, max(time) last_t, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles'",
          "claim": "All 1632 frontend calls to profile.Profile/GetProfiles return Error in about 0.01 ms, from 05:16:18 onward."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE level='ERROR' GROUP BY ALL ORDER BY n DESC",
          "claim": "Frontend logs about 1206 ERROR entries 'Get profiles failed' in the abnormal window, versus about 1 per minute normally."
        }
      ]
    }
  ]
}
```

